<?php
namespace App\Http\Controllers;use App\Models\WalletTopUp;use App\Services\{AuditLogger};use App\Services\Wallet\WalletService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Http;
class WalletWebhookController extends Controller{public function __invoke(Request$r,WalletService$s,AuditLogger$a){$secret=config('services.razorpay.webhook_secret');$sig=(string)$r->header('X-Razorpay-Signature');if(!$secret||!$sig||!hash_equals(hash_hmac('sha256',$r->getContent(),$secret),$sig))return response()->json(['message'=>'Invalid webhook signature.'],401);$event=$r->json('event');$payment=$r->json('payload.payment.entity',[]);if(!in_array($event,['payment.captured','payment.failed'],true))return response()->json(['message'=>'Event ignored.']);$t=WalletTopUp::where('provider_order_id',$payment['order_id']??null)->first();if(!$t)return response()->json(['message'=>'Top-up not found.'],404);if($event==='payment.failed'){if(!in_array($t->status,['paid','refunded'],true))$t->update(['status'=>'failed','failed_at'=>now()]);$a->log('wallet.payment_failed',$t,null,[],[],['studio_owner_id'=>$t->studio_owner_id]);return response()->json(['message'=>'Payment failure recorded.']);}$order=Http::withBasicAuth(config('services.razorpay.key_id'),config('services.razorpay.key_secret'))->acceptJson()->get('https://api.razorpay.com/v1/orders/'.$t->provider_order_id);if($order->failed())return response()->json(['message'=>'Temporary gateway error.'],503);$valid=($payment['status']??null)==='captured'&&($payment['order_id']??null)===$t->provider_order_id&&(int)($payment['amount']??0)===$t->total_amount_minor&&($payment['currency']??null)===$t->currency&&$order->json('id')===$t->provider_order_id&&(int)$order->json('amount')===$t->total_amount_minor&&$order->json('currency')===$t->currency&&$order->json('status')==='paid';if(!$valid)return response()->json(['message'=>'Payment details do not match the top-up.'],422);$s->credit($t,(string)$payment['id']);$a->log('wallet.payment_confirmed',$t,null,[],[],['studio_owner_id'=>$t->studio_owner_id,'credit_units'=>$t->credit_units,'money_amount_minor'=>$t->base_amount_minor]);return response()->json(['message'=>'Credits added successfully.']);}}
